/**
* Returns geoJSON with stops. A `route_id` query parameter may be passed to
* find all stops for a route. A `trip_id` query parameter may be passed to
* find all stops for a trip. A `direction_id` query parameter may be passed
* to find all stops for a direction.
* @param query Column values to match, as single values or arrays
* @param options Query options, including the database to read from
* @returns A GeoJSON FeatureCollection of stop points, each carrying its stop
*          attributes, serving routes, and agency name. Stops belonging to no
*          route are omitted
*/
function getStopsAsGeoJSON(query = {}, options = {}) {
	const db = options.db ?? openDb();
	const stops = getStops(query, [], [], options);
	const agencies = getAgencies({}, [], [], options);
	const filteredStops = stops.map((stop) => {
		const routes = db.prepare(`SELECT * FROM routes WHERE route_id IN (SELECT DISTINCT route_id FROM trips WHERE trip_id IN (SELECT DISTINCT trip_id FROM stop_times WHERE stop_id = ?))`).all(stop.stop_id);
		const stopAttributes = getStopAttributes({ stop_id: stop.stop_id }, [], [], options);
		return {
			...stop,
			...stopAttributes?.[0] || [],
			routes: orderBy(routes, (route) => route?.route_short_name ? Number.parseInt(route.route_short_name, 10) : 0),
			agency_name: agencies[0]?.agency_name ?? null
		};
	}).filter((stop) => stop.routes.length > 0);
	return stopsToGeoJSONFeatureCollection(filteredStops);
}

